from abc import ABC, abstractmethod

class Animal(ABC):            # abstraction
    def __init__(self, name):
        self._name = name     # encapsulation
    @abstractmethod
    def speak(self):
        pass

class Dog(Animal):            # inheritance
    def speak(self):          # polymorphism
        return 'woof'

class Cat(Animal):
    def speak(self):
        return 'meow'

