# Python: abstract base class (both roles)
from abc import ABC, abstractmethod

class Payment(ABC):
    def log(self):                    # implemented — shared code
        print('processing')
    @abstractmethod
    def pay(self, amount):            # contract — subclasses implement
        pass

class Card(Payment):
    def pay(self, amount):
        self.log()
        print(f'card: {amount}')

